WITH upd AS (
  UPDATE pending_review SET status = 'rejected' WHERE video_id = $1 AND status = 'pending' RETURNING video_id
)
SELECT $1::text AS video_id, $2::text AS callback_query_id, $3::bigint AS message_id, $4::bigint AS chat_id, $5::text AS update_id, (SELECT count(*) FROM upd) AS updated;

