const fs = require('fs');
const path = require('path');
const item = $input.item.json;

const BASE = '/home/node/.n8n/obsidian/DB_Obsidian/╨Ь╨Ю╨Щ ╨в╨а╨Х╨Щ╨Ф╨Ш╨Э╨У';
const partFolder = (item.part || '╨з╨░╤Б╤В╤М 13. ╨Я╨а╨Ю╨з╨Х╨Х').replace(/[/\\]/g, ' тАФ ');
