    chunk_index: item.chunk_index || 1,
    chunk_total: item.chunk_total || 1
  }
};

const fs = require('fs');
const path = require('path');

const httpResponses = $input.all().map((i) => i.json);
const sbors = $('╨б╨▒╨╛╤А╨║╨░ ╨╖╨░╨┐╤А╨╛╤Б╨░ ╨┤╨╛╨╖╨░╨┐╨╕╤Б╨╕').all().map((i) => i.json);
const metas = $('╨з╤В╨╡╨╜╨╕╨╡ ╤Д╨░╨╣╨╗╨░ ╨│╨╗╨░╨▓╤Л').all().map((i) => i.json);
const results = httpResponses.map((resp, i) => ({ ...resp, ...(sbors[i] || {}) }));

const groups = {};
for (const r of results) {
  const g = groups[r.video_id];
  if (!g) groups[r.video_id] = [r];
  else g.push(r);
}

function extractBlock(raw) {
  const cleaned = String(raw || '').replace(/```json/gi, '').replace(/```/g, '').trim();
  if (!cleaned) return { text: null };
  const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try {
      const obj = JSON.parse(jsonMatch[0]);
      const b = obj.block || obj.text || obj.markdown || null;
      if (b && String(b).trim()) return { text: String(b).trim() };
    } catch (e) {}
  }
  const m = cleaned.match(/"block"\s*:\s*"((?:[^"\\]|\\.)*)"/);
  if (m) {
    try {
      const b = JSON.parse('"' + m[1] + '"');
      if (b && b.trim()) return { text: b.trim() };
    } catch (e) {}
  }
  if (cleaned.length >= 50 && !cleaned.startsWith('{') && /[╨Р-╨п╨░-╤ПA-Za-z]{3}/.test(cleaned)) {
    return { text: cleaned };
  }
  return { text: null };
}

const out = [];
for (const [videoId, chunks] of Object.entries(groups)) {
  const meta = metas.find((m) => m.video_id === videoId) || {};
  const parsed = [];
  const parseErrors = [];
  for (const c of chunks) {
    const idx = c.chunk_index || 1;
    const raw = c.choices?.[0]?.message?.content || '';
    const r = extractBlock(raw);
    if (r.text) parsed.push({ idx, text: r.text });
    else parseErrors.push('╤Д╤А╨░╨│╨╝╨╡╨╜╤В ' + idx + ': ╨┐╤Г╤Б╤В╨╛╨╣ ╨╛╤В╨▓╨╡╤В LLM');
  }
  parsed.sort((a, b) => a.idx - b.idx);
  const missing = chunks.length - parsed.length;
  if (missing > 0) parseErrors.push('╤Б╨╛╨▒╤А╨░╨╜╨╛ ' + parsed.length + ' ╨╕╨╖ ' + chunks.length + ' ╤Д╤А╨░╨│╨╝╨╡╨╜╤В╨╛╨▓ тАФ ╨╖╨░╨┐╨╕╤Б╤М ╨╛╤В╨╝╨╡╨╜╨╡╨╜╨░');

  let written = false;
  let skippedDuplicate = false;
  try {
    if (parseErrors.length === 0 && meta.video_url && String(meta.existingContent || '').includes(meta.video_url)) {
      written = true; skippedDuplicate = true;
    } else if (parseErrors.length === 0) {
      const block = parsed.map((p) => p.text).join('\n\n');
      const today = new Date().toISOString().split('T')[0];
      const videoTitle = (meta.file_name || '').replace(/\.md$/i, '');
      const header = '\n\n---\n### ' + today + ' тАФ ' + videoTitle + '\nЁЯФЧ ' + meta.video_url + '\n\n';
      let current = meta.existingContent || '';
      try { current = fs.readFileSync(meta.fullPath, 'utf8'); } catch (e) {}
      if (meta.video_url && String(current).includes(meta.video_url)) {
        written = true; skippedDuplicate = true;
      } else {
        const dir = path.dirname(meta.fullPath);
        if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
        fs.writeFileSync(meta.fullPath, current + header + block, 'utf8');
        written = true;
      }
    }
  } catch (e) {
    parseErrors.push('Write error: ' + e.message);
  }

  out.push({
    json: {
      video_id: meta.video_id,
      channel_name: meta.channel_name, video_url: meta.video_url,
      file_name: meta.file_name, part: meta.part, chapter: meta.chapter, fullPath: meta.fullPath,
      chunks: chunks.length, skipped_duplicate: skippedDuplicate, written: written,
      parseError: parseErrors.length ? parseErrors.join('; ') : null,
      chat_id: meta.chat_id, message_id: meta.message_id
    }
  });
}

if (out.length === 0) {
  out.push({ json: { video_id: null, written: false, parseError: '╨╜╨╡╤В ╤Д╤А╨░╨│╨╝╨╡╨╜╤В╨╛╨▓ ╨╜╨░ ╨▓╤Е╨╛╨┤╨╡' } });
}

return out;
